using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class RyszardKapuściński
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Do tego, żeby uprawiać dziennikarstwo, przede wszystkim trzeba być dobrym człowiekiem. Źli ludzie nie mogą być dobrymi dziennikarzami.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "W krajach, w których panuje wolność słowa, wolność dziennikarza ograniczają interesy dziennika, dla którego pracuje.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wystarczy wyciągnąć rękę, aby objąć dziewczynę, ale wystarczy także przejść kilka kroków, aby pochylić się nad trumną.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeżeli ktoś idąc z orężem w ręku wysunie się o krok przed historię, musi zginąć.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Na szczytach nigdy nie jest ciepło. Wieją lodowate wichry, każdy stoi skulony i musi pilnować się, żeby sąsiad nie strącił go w przepaść.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Przychodzą takie momenty, kiedy najmniejsze zdarzenie, ot, drobiazg zupełny, głupstwo byle jakie, wywoła rewolucję i rozpęta wojnę.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Żaden pałac nie runie sam z siebie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Dyktatura nigdy nie upada stopniowo i po trochu, tylko zawsze momentalnie i całkowicie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Świat wyglądałby inaczej, gdyby powiedzieć każdemu: zbawiaj się na własną rękę, na miarę swoich chęci i możliwości!", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "W polityce trzeba umieć czekać. Kto lepiej czeka, ten wygrywa.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Historia jest często produktem bezmyślności. Jest bękartem ludzkiej głupoty, płodem zaćmienia, idiotyzmu i szaleństwa.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Ludzie nie głodują dlatego, że na świecie nie ma żywności. Jest jej pełno, w nadmiarze. Ale między tymi, którzy chcą jeść, a pełnymi magazynami stoi wysoka przeszkoda: gra polityczna.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Poranek i zmierzch – to najprzyjemniejsze godziny w Afryce. Słońce jeszcze nie pali albo już nie doskwiera – daje istnieć, daje żyć.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Co to jest szachownica Stalina? On tak porozsiedlał narody, tak je pomieszał i poprzestawiał, że teraz nie można nikogo ruszyć, żeby nie ruszyć kogoś innego.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jednakże cywilizacja, która nie zadaje pytań, która wyrzuca poza swój obręb cały – wyrażający się właśnie pytaniami – świat niepokoju, krytycyzmu i poszukiwań, jest cywilizacją stojącą w miejscu.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Kwiaty nie pachną dla siebie, tylko zawsze dla kogoś.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Stalin za kontakt z cudzoziemcem zsyłał na pięć, dziesięć lat do łagru, a często kazał rozstrzeliwać, jak się więc dziwić ludziom, że boją się cudzoziemca jak ognia.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Światu grożą trzy plagi, trzy zarazy. Pierwsza – to plaga nacjonalizmu. Druga – to plaga rasizmu. Trzecia – to plaga religijnego fundamentalizmu.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Zachód, który Rosja fascynuje, ale i napawa lękiem, gotów jest zawsze przyjść jej z pomocą, choćby w interesie własnego spokoju.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Żeby utrzymać wielkie przestrzenie, Rosjanin musi utrzymywać wielkie państwo, na utrzymanie wielkiego państwa wydaje on swoją energię.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Cenę niewolnika ustalało się według jakości uzębienia. Ludzie wyrywali sobie zęby albo piłowali je kamieniami, żeby mieć niską wartość rynkową.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Żeby zrozumieć współczesny świat, należy posługiwać się ruchomym globusem i przyglądać się scenie, na której żyjemy, z różnych punktów ziemi.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Boję się świata bez wartości, bez wrażliwości, bez myślenia. Świata, w którym wszystko jest możliwe. Ponieważ wówczas najbardziej możliwe jest zło.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Im wyższy szczebel, na którym dokonano zbrodni, tym większe prawdopodobieństwo, że będzie ona uznana nie za zbrodnię, lecz za konieczne posunięcie polityczne.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeżeli jestem sam w lesie, nie może mnie spotkać żadna podłość, nie mogę usłyszeć kłamstwa ani świstu bata.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeżeli spośród wielu prawd wybierzesz tylko jedną i za tą jedną będziesz ślepo podążać, zmieni się ona w fałsz, a ty staniesz się fanatykiem.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Kiedy pojawiają się pytania, na które nie ma odpowiedzi, oznacza to, że nastąpił kryzys.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Kraje, które nie przyjmą do siebie ludzi z Trzeciego Świata, same zamienią się w Trzeci Świat.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Nasze ocalenie? W dążeniu do osiągnięcia rzeczy niemożliwych do osiągnięcia.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "O każdej drodze lubię myśleć, że jest ona drogą bez końca, że biegnie dookoła świata.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Rasistą jest człowiek prymitywny, bezmyślny.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Stopnie barbarzyństwa: najpierw niszczy się tych, którzy tworzą wartości.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "System anachroniczny to taki, który udziela starych odpowiedzi na nowe pytania.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Kiedy się spieszysz, nic nie widzisz, nic nie przeżywasz, niczego nie doświadczasz, nie myślisz!", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Oto jest świat współczesny – nigdzie ciszy zupełnej. Żeby dotrzeć do takiej ciszy, trzeba urządzać specjalne wyprawy.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Istnieje coś takiego jak zarażenie podróżą i jest to rodzaj choroby w gruncie rzeczy nieuleczalnej.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Los musi się dopełnić, nie można go zmienić ani uniknąć, choćby prowadził w przepaść.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Tylko dzieci zadają ważne pytania i naprawdę chcą się czegoś dowiedzieć.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "W swoim postępowaniu człowiek nie ma wyboru. Nosi w sobie swój los, jakby to był kod genetyczny.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wspólne dzieje i legendy umacniają wspólnotę, a człowiek może istnieć tylko we wspólnocie, dzięki niej.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeżeli ktoś był na stanowisku i nie kradł, robiło się wokół niego pusto: wzbudzał podejrzenie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Bar afrykański to Forum starożytnego Rzymu, to rynek średniowiecznego miasteczka, to paryska winiarnia Robespierre’a.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Człowiek, który przeżył wielką wojnę, jest inny od tego, który nie przeżył żadnej wojny. Są to dwa różne gatunki ludzi.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Istotą kraju kolonialnego jest to, że w życiu kraju podbitego wytwarza on całe szeregi przepaści.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Kto chce wiedzieć, ile trzeba zapłacić, żeby wygrać wojnę, niech zobaczy nasze cmentarze.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Małe kraje z trzeciego, czwartego i dalszych światów mają szanse wzbudzić żywsze zainteresowanie dopiero wówczas, kiedy zdecydują się na przelew krwi.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wszystko staje w poprzek drogi: wielowiekowe zacofanie, prymitywna gospodarka, analfabetyzm, fanatyzm religijny, zaślepienie plemienne.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Chętnie idziemy śladem mistyków, ponieważ wierzymy, że wiedzą, dokąd idą. Ale oni też błądzą.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Często o wartości przedmiotu decyduje w naszych oczach nawet nie on sam, ale otoczenie, w jakim go ujrzymy, jego kontekst, oprawa.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "I nie zostało mi nic oprócz Boga – to znaczy, zostało wszystko, jeżeli wierzysz.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Język mówiony czy pisany ogranicza i krępuje choćby przez swoją dosłowność, przez natychmiastową i prostą sprawdzalność.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Największa słabość kultury – że nie jest w stanie powstrzymać zbrodni.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Sztuka jest arystokratyczna. Kultura może być masowa, sztuka – nigdy. Sztuka – to arystokracja kultury.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Więc albo zaczniemy się nienawidzić, zwalczać, tępić, postrzegać innego jako wroga naszej kultury czy religii, albo zaczniemy szukać zrozumienia i wzajemnego poznania.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Bo władzę ma ten, w czyich rękach jest studio telewizyjne, a szerzej – media w ogóle.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Dziennikarz, który się specjalizuje jako korespondent wojenny, idzie czasem z jakimś oddziałem na akcję i wtedy czuje się z nim związany.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Informacja stała się towarem, a świat mediów uzależnił się od świata realnego i zaczął żyć według własnych reguł.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Nie wierzę w bezstronne dziennikarstwo, nie wierzę w formalny obiektywizm. Dziennikarz nie może być obojętnym świadkiem, powinien posiadać zdolność, którą w psychologii nazywa się empatią.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Odkąd odkryto, że informacja jest towarem przynoszącym krociowe zyski, przestała ona podlegać tradycyjnym kryteriom prawdy i kłamstwa.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Procesowi przyspieszenia informacji towarzyszy zjawisko jej spłycenia.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Radio ma tę samą właściwość, co i książka: umie stworzyć swoje audytorium. Telewizja nie ma swojego audytorium.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Słowa staniały. Rozmnożyły się, ale straciły na wartości. Są wszędzie. Jest ich dużo. Mrowią się, kłębią, dręczą jak chmary natarczywych much.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Człowiek napotkawszy przeszkodę, której nie może zniszczyć – zaczyna niszczyć sam siebie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Fanatycy to ludzie pozbawieni słuchu.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Im wyższy postawisz sobie cel, tym bardziej będziesz samotny.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeden cham zburzy przyjemną zabawę, natomiast jeden kulturalny człowiek to zbyt mało, aby podnieść poziom zabawy chamów.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jest coraz więcej ludzi bezczynnych, coraz więcej aktorów, dla których w rozgrywającej się sztuce świata nie ma roli i miejsca na scenie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeżeli trzecia część społeczeństwa żyje w nędzy, całe społeczeństwo jest zdemoralizowane.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Każdy z uczestników i świadków wydarzenia widzi je inaczej – dlatego relacje będą różnić się diametralnie.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Każde plemię uważało się dawniej za całą ludzkość.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Pisać o tłumie jest łatwiej niż o pojedynczym człowieku. Masa upraszcza, człowiek w masie jest uproszczony.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Polityka, jeżeli długo się nią zajmować, paczy, korumpuje umysł.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Rzeczywiste barbarzyństwo zaczyna się w momencie, kiedy nikt już nie potrafi ocenić, nikt już nie wie, że to, co czyni, jest barbarzyństwem.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Siłą myśli europejskiej była zawsze zdolność do samokrytyki. W tradycji europejskiej każdy wielki kryzys wyzwalał głęboką refleksję samokrytyczną.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Stopniowo, w miarę upływu czasu, odkrywamy w samym sobie coraz trudniejszego przeciwnika.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wiele rzeczy zaczynamy rozumieć późno, jeszcze więcej – bardzo późno, najwięcej – zbyt późno.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "W polityce nie trzeba nic robić, bo połowy problemów i tak się nie rozwiąże, a połowa rozwiąże się sama.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "W wielu krajach świata jedyny dowód, że państwo istnieje, to obecność w jego stolicy obcych ambasad.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wymyśliliśmy maszyny, które pozwalają nam nie myśleć.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "XXI wiek będzie wielokulturowy, będzie wiekiem rozbudzonych ambicji. Ludzkość nie przeżyje go, jeżeli nie nauczy się tej podstawowej prawdy: że drugi ma też prawo do życia i ma prawo do tego, by być uznanym.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Czy pisanie może cokolwiek zmienić? Tak. Głęboko w to wierzę.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Ja strasznie dużo pracuję nad tekstem. Żeby napisać jedno własne zdanie, trzeba przeczytać tysiące cudzych.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Jeśli uda mi się jednego dnia zapełnić stronę, uważam, że to był dobry dzień.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Ogromnie cenię poetów, ponieważ jest to jedyna grupa, dla której tak ważny jest język.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Pisanie wierszy pozwala dotknąć żywego języka, zbadać jego granice, docenić wartość samego słowa i metafory pozbawionych pobocznych wzmocnień.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Pisząc reportaże, niekiedy chętnie uciekałem w poezję. Jest wiele fragmentów, o których czasami myślę, że można by je zebrać i wydać jako wiersze lub poematy prozą.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Pisząc wiersz, odkrywamy w sobie inność, o którą się nie podejrzewaliśmy, zanim usiedliśmy nad kartką.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Stawiam kobiety wyżej niż mężczyzn. Są bliższe prawdy o życiu.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Wiemy o świecie tyle, ile chcą wiedzieć wielkie sieci telewizji świata. One nie uprawiają cenzury, ale manipulację.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Czy fakt jest prawdą? Tak, ale fakt bez kontekstu nie jest całą prawdą, a nawet może mieć wymowę przeciwną do jego rzeczywistego sensu.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Gdyby nie było chamstwa, nie byłoby faszyzmu. Chamstwo jest nosicielem pogardy i przemocy, podłości i woli zniszczenia.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Nie ma gorszego połączenia niż broń, głupota i strach. Wszystkiego najgorszego można się wówczas spodziewać.", Author = "Ryszard Kapuściński" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Ryszard_Kapuściński", Text = "Żołnierz musi mieć poczucie, że to, co robi, jest komuś potrzebne, jest dla kogoś ważne, że ktoś na niego patrzy i ktoś mu pomaga, jest z nim.", Author = "Ryszard Kapuściński" },
        };
    }
}
